import Foundation

/// A YouTube video's id from an address, its caption tracks from YouTube's player answer, the track to read, and the
/// caption file as plain text.
public enum YouTubeVideo {
    public struct Track: Sendable, Equatable {
        public let language: String
        /// Generated by speech recognition rather than written by someone.
        public let isAutomatic: Bool
        public let url: URL

        public init(language: String, isAutomatic: Bool, url: URL) {
            self.language = language
            self.isAutomatic = isAutomatic
            self.url = url
        }
    }

    public struct Details: Sendable, Equatable {
        public let title: String
        public let isPlayable: Bool
        public let tracks: [Track]

        public static let unknown = Details(title: "", isPlayable: false, tracks: [])
    }

    /// Watch, youtu.be, shorts, embed and live links; not a look-alike host such as "notyoutube.com".
    private static let address = try? NSRegularExpression(
        pattern: #"(?<![\w.-])(?:https?://)?(?:(?:www|m|music)\.)?(?:youtube(?:-nocookie)?\.com/(?:watch\?(?:\S*?&)?v=|shorts/|embed/|live/|v/)|youtu\.be/)([A-Za-z0-9_-]{11})(?![A-Za-z0-9_-])"#,
        options: [.caseInsensitive])

    /// The video of the first YouTube address in `text`.
    public static func id(in text: String) -> String? {
        let range = NSRange(text.startIndex..., in: text)
        guard let match = address?.firstMatch(in: text, range: range), let id = Range(match.range(at: 1), in: text) else {
            return nil
        }
        return String(text[id])
    }

    /// YouTube's player answer; anything missing reads as no title, not playable or no captions. Only caption
    /// addresses on youtube.com over https are kept.
    public static func details(fromPlayer data: Data) -> Details {
        guard let player = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] else { return .unknown }
        let title = (player["videoDetails"] as? [String: Any])?["title"] as? String ?? ""
        let isPlayable = (player["playabilityStatus"] as? [String: Any])?["status"] as? String == "OK"
        let renderer = (player["captions"] as? [String: Any])?["playerCaptionsTracklistRenderer"] as? [String: Any]
        let entries = renderer?["captionTracks"] as? [[String: Any]] ?? []
        let tracks = entries.compactMap { entry -> Track? in
            guard let language = entry["languageCode"] as? String, !language.isEmpty,
                  let address = entry["baseUrl"] as? String, let url = plainFormat(address) else { return nil }
            return Track(language: language, isAutomatic: entry["kind"] as? String == "asr", url: url)
        }
        return Details(title: title, isPlayable: isPlayable, tracks: tracks)
    }

    /// Without `fmt`, the caption service answers in its simplest XML (`<text>` elements).
    private static func plainFormat(_ address: String) -> URL? {
        guard var components = URLComponents(string: address), components.scheme?.lowercased() == "https",
              let host = components.host?.lowercased(), host == "youtube.com" || host.hasSuffix(".youtube.com") else { return nil }
        components.percentEncodedQueryItems = components.percentEncodedQueryItems?.filter { $0.name != "fmt" }
        return components.url
    }

    /// In the preferred language, written before generated; else in the language the video speaks (that of its
    /// generated track); else English; else any written track; else whatever there is.
    public static func track(in tracks: [Track], preferring preferred: String) -> Track? {
        let base = { (track: Track) in track.language.split(separator: "-").first.map { $0.lowercased() } ?? "" }
        let spoken = tracks.first(where: \.isAutomatic).map(base)
        var languages: [String] = []
        for language in [preferred.lowercased(), spoken, "en"].compactMap({ $0 }) where !languages.contains(language) {
            languages.append(language)
        }
        for language in languages {
            for automatic in [false, true] {
                if let found = tracks.first(where: { base($0) == language && $0.isAutomatic == automatic }) { return found }
            }
        }
        return tracks.first { !$0.isAutomatic } ?? tracks.first
    }

    /// The caption file's text in one piece: the simple format (`<text>`) and the timed one (`<p>` with `<s>` words).
    /// What arrived of a broken file is kept.
    public static func transcript(from data: Data) -> String {
        let reader = CaptionReader()
        let parser = XMLParser(data: data)
        parser.delegate = reader
        parser.parse()
        return reader.lines.joined(separator: " ")
    }

    private final class CaptionReader: NSObject, XMLParserDelegate {
        private static let lineElements: Set<String> = ["text", "p"]
        private(set) var lines: [String] = []
        private var current: String?

        func parser(_ parser: XMLParser, didStartElement elementName: String, namespaceURI: String?,
                    qualifiedName: String?, attributes: [String: String] = [:]) {
            if Self.lineElements.contains(elementName) { current = "" }
        }

        func parser(_ parser: XMLParser, foundCharacters string: String) {
            current? += string
        }

        func parser(_ parser: XMLParser, didEndElement elementName: String, namespaceURI: String?, qualifiedName: String?) {
            guard Self.lineElements.contains(elementName), let text = current else { return }
            current = nil
            // The simple format escapes twice: "&amp;#39;" arrives as "&#39;".
            let line = HTMLText.decodingEntities(text).split(whereSeparator: \.isWhitespace).joined(separator: " ")
            if !line.isEmpty { lines.append(line) }
        }
    }
}
